"""Shell grammar parser.

Produces an AST from a token stream produced by lexer.tokenize().

AST node types (all are dicts with a 'kind' field):

    {'kind': 'list', 'items': [...], 'ops': [...]}
        A list of and-or expressions separated by ';' or '&'.

    {'kind': 'and_or', 'pipes': [...], 'ops': [...]}
        A sequence of pipelines joined by '&&' or '||'.

    {'kind': 'pipeline', 'cmds': [...]}
        One or more simple/compound commands joined by '|'.

    {'kind': 'simple', 'assigns': [...], 'argv': [...], 'redirs': [...]}
        A simple command.  argv is a list of "word forms" (see lexer).

    {'kind': 'if', 'branches': [(cond, body), ...], 'else': body_or_None, 'redirs': []}
    {'kind': 'for', 'var': str, 'items': [word_forms], 'body': list, 'redirs': []}
    {'kind': 'while', 'cond': list, 'body': list, 'negate': False, 'redirs': []}
    {'kind': 'case', 'word': word_form, 'items': [(patterns, body), ...], 'redirs': []}
    {'kind': 'group', 'body': list, 'redirs': []}
    {'kind': 'subshell', 'body': list, 'redirs': []}
    {'kind': 'func', 'name': str, 'body': list}
"""


class ParseError(Exception):
    pass


class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self, off=0):
        return self.tokens[self.pos + off]

    def advance(self):
        t = self.tokens[self.pos]
        self.pos += 1
        return t

    def expect_op(self, op):
        t = self.peek()
        if t.kind != "OP" or t.value != op:
            raise ParseError("expected %r, got %r" % (op, (t.kind, t.value)))
        self.advance()

    def skip_newlines(self):
        while self.peek().kind == "NEWLINE":
            self.advance()

    # ---- top-level ----
    def parse_program(self):
        """Parse a full program (sequence of statements)."""
        items = []
        self.skip_newlines()
        while self.peek().kind != "EOF":
            stmt = self.parse_and_or_list()
            if stmt is not None:
                items.append(stmt)
            # separators
            while self.peek().kind == "NEWLINE" or (
                self.peek().kind == "OP" and self.peek().value in (";", "&")
            ):
                self.advance()
        return items

    def parse_and_or_list(self):
        """Parse a list terminated by ; & newline or end tokens."""
        and_or = self.parse_and_or()
        return and_or

    # ---- and-or ----
    def parse_and_or(self):
        pipes = [self.parse_pipeline()]
        ops = []
        while self.peek().kind == "OP" and self.peek().value in ("&&", "||"):
            ops.append(self.advance().value)
            # Allow newlines after && or ||
            self.skip_newlines()
            pipes.append(self.parse_pipeline())
        if len(pipes) == 1 and not ops:
            return pipes[0]
        return {"kind": "and_or", "pipes": pipes, "ops": ops}

    # ---- pipeline ----
    def parse_pipeline(self):
        negate = False
        if (
            self.peek().kind == "WORD"
            and _word_literal(self.peek()) == "!"
        ):
            negate = True
            self.advance()
        cmds = [self.parse_command()]
        while self.peek().kind == "OP" and self.peek().value == "|":
            self.advance()
            self.skip_newlines()
            cmds.append(self.parse_command())
        if len(cmds) == 1 and not negate:
            return cmds[0]
        return {"kind": "pipeline", "cmds": cmds, "negate": negate}

    # ---- command ----
    def parse_command(self):
        t = self.peek()
        if t.kind == "WORD":
            lit = _word_literal(t)
            if lit == "if":
                return self.parse_if()
            if lit == "for":
                return self.parse_for()
            if lit == "while":
                return self.parse_while(negate=False)
            if lit == "until":
                return self.parse_while(negate=True)
            if lit == "case":
                return self.parse_case()
            # Function: name ( ) { ... }
            if (
                self.peek(1).kind == "OP"
                and self.peek(1).value == "("
                and self.peek(2).kind == "OP"
                and self.peek(2).value == ")"
            ):
                return self.parse_function()
            return self.parse_simple()
        if t.kind == "OP" and t.value == "(":
            return self.parse_subshell()
        if t.kind == "OP" and t.value == "{":
            return self.parse_group()
        raise ParseError("unexpected token %r" % ((t.kind, t.value),))

    def parse_simple(self):
        assigns = []
        argv = []
        redirs = []
        # Leading assignments.
        while self.peek().kind == "WORD" and _is_assignment(self.peek()):
            assigns.append(_split_assignment(self.advance()))
        while True:
            t = self.peek()
            if t.kind == "WORD":
                # Check for number-prefixed redirection like 2>...
                word = t
                # Redirection detection: if the word is a lone number and the
                # next token is a redirection operator, treat as redir.
                lit = _word_literal(word)
                if (
                    lit is not None
                    and lit.isdigit()
                    and self.peek(1).kind == "OP"
                    and self.peek(1).value in (">", ">>", "<", ">&", "<&")
                ):
                    fd = int(lit)
                    self.advance()  # consume fd
                    op = self.advance().value
                    target = self.advance()
                    redirs.append({"fd": fd, "op": op, "target": target})
                    continue
                argv.append(self.advance())
                continue
            if t.kind == "OP" and t.value in (">", ">>", "<", ">&", "<&"):
                op = self.advance().value
                target = self.advance()
                default_fd = 0 if op in ("<", "<&") else 1
                redirs.append({"fd": default_fd, "op": op, "target": target})
                continue
            break
        return {"kind": "simple", "assigns": assigns, "argv": argv, "redirs": redirs}

    def parse_redirs_trailing(self):
        redirs = []
        while True:
            t = self.peek()
            if t.kind == "WORD":
                lit = _word_literal(t)
                if (
                    lit is not None
                    and lit.isdigit()
                    and self.peek(1).kind == "OP"
                    and self.peek(1).value in (">", ">>", "<", ">&", "<&")
                ):
                    fd = int(lit)
                    self.advance()
                    op = self.advance().value
                    target = self.advance()
                    redirs.append({"fd": fd, "op": op, "target": target})
                    continue
            if t.kind == "OP" and t.value in (">", ">>", "<", ">&", "<&"):
                op = self.advance().value
                target = self.advance()
                default_fd = 0 if op in ("<", "<&") else 1
                redirs.append({"fd": default_fd, "op": op, "target": target})
                continue
            break
        return redirs

    # ---- compound commands ----
    def parse_if(self):
        self.advance()  # 'if'
        branches = []
        else_body = None
        cond = self.parse_compound_list_until({"then"})
        self._expect_word("then")
        body = self.parse_compound_list_until({"elif", "else", "fi"})
        branches.append((cond, body))
        while self._peek_word() == "elif":
            self.advance()
            cond2 = self.parse_compound_list_until({"then"})
            self._expect_word("then")
            body2 = self.parse_compound_list_until({"elif", "else", "fi"})
            branches.append((cond2, body2))
        if self._peek_word() == "else":
            self.advance()
            else_body = self.parse_compound_list_until({"fi"})
        self._expect_word("fi")
        redirs = self.parse_redirs_trailing()
        return {
            "kind": "if",
            "branches": branches,
            "else": else_body,
            "redirs": redirs,
        }

    def parse_for(self):
        self.advance()  # 'for'
        name_tok = self.advance()
        if name_tok.kind != "WORD":
            raise ParseError("expected variable after 'for'")
        name = _word_literal(name_tok)
        # optional 'in' <words> ; / newline
        self.skip_newlines()
        items = None
        if self._peek_word() == "in":
            self.advance()
            items = []
            while self.peek().kind == "WORD":
                items.append(self.advance())
            # semicolon or newline terminates the 'in' clause
            self._skip_separators()
        else:
            self._skip_separators()
        self._expect_word("do")
        body = self.parse_compound_list_until({"done"})
        self._expect_word("done")
        redirs = self.parse_redirs_trailing()
        return {
            "kind": "for",
            "var": name,
            "items": items,
            "body": body,
            "redirs": redirs,
        }

    def parse_while(self, negate):
        self.advance()  # 'while' or 'until'
        cond = self.parse_compound_list_until({"do"})
        self._expect_word("do")
        body = self.parse_compound_list_until({"done"})
        self._expect_word("done")
        redirs = self.parse_redirs_trailing()
        return {
            "kind": "while",
            "cond": cond,
            "body": body,
            "negate": negate,
            "redirs": redirs,
        }

    def parse_case(self):
        self.advance()  # 'case'
        word_tok = self.advance()
        if word_tok.kind != "WORD":
            raise ParseError("expected word after 'case'")
        self.skip_newlines()
        self._expect_word("in")
        self.skip_newlines()
        items = []
        while True:
            self.skip_newlines()
            if self._peek_word() == "esac":
                self.advance()
                break
            # Optional leading (
            if self.peek().kind == "OP" and self.peek().value == "(":
                self.advance()
            patterns = []
            while True:
                if self.peek().kind != "WORD":
                    raise ParseError("expected pattern in case")
                patterns.append(self.advance())
                if self.peek().kind == "OP" and self.peek().value == "|":
                    self.advance()
                    continue
                break
            if not (self.peek().kind == "OP" and self.peek().value == ")"):
                raise ParseError("expected ) in case")
            self.advance()
            body = self.parse_compound_list_until_op(";;") or []
            # Consume ';;'
            if self.peek().kind == "OP" and self.peek().value == ";;":
                self.advance()
            items.append((patterns, body))
        redirs = self.parse_redirs_trailing()
        return {"kind": "case", "word": word_tok, "items": items, "redirs": redirs}

    def parse_subshell(self):
        self.expect_op("(")
        body = self.parse_compound_list_until_op(")")
        self.expect_op(")")
        redirs = self.parse_redirs_trailing()
        return {"kind": "subshell", "body": body, "redirs": redirs}

    def parse_group(self):
        self.expect_op("{")
        body = self.parse_compound_list_until({"}"})
        # } is a reserved word token, but here arrives as OP token if the lexer
        # tokenized it as such. In our lexer, { and } are OP.
        if self.peek().kind == "OP" and self.peek().value == "}":
            self.advance()
        else:
            self._expect_word("}")
        redirs = self.parse_redirs_trailing()
        return {"kind": "group", "body": body, "redirs": redirs}

    def parse_function(self):
        name_tok = self.advance()
        self.expect_op("(")
        self.expect_op(")")
        self.skip_newlines()
        # Body must be a compound command (usually a group).
        body_cmd = self.parse_command()
        return {"kind": "func", "name": _word_literal(name_tok), "body": body_cmd}

    # ---- helpers ----
    def parse_compound_list_until(self, stop_words):
        """Parse a compound list until encountering one of the stop words.

        Stop words are recognized by literal WORD token value.
        """
        items = []
        while True:
            self.skip_newlines()
            if self.peek().kind == "EOF":
                break
            pw = self._peek_word()
            if pw in stop_words:
                break
            if self.peek().kind == "OP" and self.peek().value == "}" and "}" in stop_words:
                break
            stmt = self.parse_and_or_list()
            if stmt is not None:
                items.append(stmt)
            while self.peek().kind == "NEWLINE" or (
                self.peek().kind == "OP" and self.peek().value in (";", "&")
            ):
                self.advance()
        return items

    def parse_compound_list_until_op(self, op):
        items = []
        while True:
            self.skip_newlines()
            if self.peek().kind == "EOF":
                break
            if self.peek().kind == "OP" and self.peek().value == op:
                break
            stmt = self.parse_and_or_list()
            if stmt is not None:
                items.append(stmt)
            while self.peek().kind == "NEWLINE" or (
                self.peek().kind == "OP" and self.peek().value in (";", "&")
            ):
                self.advance()
        return items

    def _peek_word(self):
        t = self.peek()
        if t.kind == "WORD":
            return _word_literal(t)
        return None

    def _expect_word(self, w):
        if self._peek_word() != w:
            t = self.peek()
            raise ParseError("expected %r, got %r" % (w, (t.kind, t.value)))
        self.advance()

    def _skip_separators(self):
        while self.peek().kind == "NEWLINE" or (
            self.peek().kind == "OP" and self.peek().value == ";"
        ):
            self.advance()


def _word_literal(tok):
    """Return the literal content of a WORD token if it is a single plain
    (unquoted) raw segment; otherwise None.
    """
    if tok.kind != "WORD":
        return None
    parts = tok.value
    if len(parts) == 1 and parts[0][0] == "R":
        return parts[0][1]
    if not parts:
        return ""
    return None


def _is_assignment(tok):
    if tok.kind != "WORD" or tok.quoted:
        return False
    parts = tok.value
    if not parts:
        return False
    # The first segment must be a raw word containing an = with a valid
    # identifier to its left.
    first = parts[0]
    if first[0] != "R":
        return False
    raw = first[1]
    eq_pos = raw.find("=")
    if eq_pos <= 0:
        return False
    name = raw[:eq_pos]
    if not (name[0].isalpha() or name[0] == "_"):
        return False
    for ch in name[1:]:
        if not (ch.isalnum() or ch == "_"):
            return False
    return True


def _split_assignment(tok):
    """Return (name, value_word_form) for an assignment-style WORD token."""
    parts = tok.value
    first = parts[0]
    raw = first[1]
    eq_pos = raw.find("=")
    name = raw[:eq_pos]
    after = raw[eq_pos + 1 :]
    rest = []
    if after != "":
        rest.append(("R", after))
    rest.extend(parts[1:])
    return (name, rest)
