"""Expansion of word forms into concrete strings."""

import os


def expand_word(word_form, shell, for_assign=False, in_assign_value=False):
    """Expand a single word form into (possibly multiple) strings.

    word_form is a list of segment tuples as produced by the lexer:
        ("R", raw)                 - raw text (unquoted)
        ("'", literal)             - single-quoted literal
        ('"', interior)            - double-quoted text (may contain $ etc)
        ("V", name)                - $name
        ("VB", inner)              - ${...}
        ("A", expr)                - $(( ... ))
        ("C", code)                - $(...) or `...`

    Returns a list of expanded strings. Splitting only happens for unquoted
    $variable/command substitution results.
    """
    if not word_form:
        return [""]

    # Build up a list of "fields" being constructed. Each field is a list of
    # (text, splittable) chunks; splittable means IFS word-splitting applies.
    pieces = []  # list of (text, splittable, quoted_presence)
    for seg in word_form:
        kind = seg[0]
        if kind == "R":
            pieces.append((seg[1], True, False))
        elif kind == "'":
            pieces.append((seg[1], False, True))
        elif kind == '"':
            # Expand $ and backticks inside double-quoted strings.
            expanded = _expand_dquote(seg[1], shell)
            pieces.append((expanded, False, True))
        elif kind == "V":
            val = shell.get_var(seg[1])
            pieces.append((val, True, False))
        elif kind == "VB":
            val = _expand_vb(seg[1], shell)
            pieces.append((val, True, False))
        elif kind == "A":
            val = str(_arith(seg[1], shell))
            pieces.append((val, True, False))
        elif kind == "C":
            val = shell.command_subst(seg[1])
            # Strip trailing newlines.
            while val.endswith("\n"):
                val = val[:-1]
            pieces.append((val, True, False))
        else:
            pieces.append((str(seg[1]), True, False))

    # Field splitting on unquoted pieces.
    ifs = shell.get_var("IFS")
    if ifs == "" and any(p[1] for p in pieces):
        # Empty IFS => no splitting.
        ifs_chars = ""
    elif ifs is None or ifs == "":
        ifs_chars = " \t\n"
    else:
        ifs_chars = ifs

    # Determine whether the word itself had any quoted chunks.
    had_quoted = any(p[2] for p in pieces)

    fields = [""]
    for text, splittable, _ in pieces:
        if splittable and ifs_chars:
            # Split text on IFS characters.
            # An unquoted empty expansion is removed entirely.
            if text == "":
                continue
            # Track which parts become new fields.
            cur = fields[-1]
            i = 0
            while i < len(text):
                ch = text[i]
                if ch in ifs_chars:
                    # End current field, skip run of IFS chars.
                    fields[-1] = cur
                    cur = ""
                    while i < len(text) and text[i] in ifs_chars:
                        i += 1
                    if i < len(text):
                        fields.append("")
                    continue
                cur += ch
                i += 1
            fields[-1] = cur
        else:
            fields[-1] = fields[-1] + text

    # Drop empty fields unless the word had quoted segments (or no expansions).
    # If there's only one field and it's empty and the word had any quoting,
    # keep it.
    if len(fields) == 1:
        if fields[0] == "" and not had_quoted and _all_splittable_empty(pieces):
            return []
        return [_pathname_expand_single(fields[0], had_quoted, shell)] if not for_assign else fields

    # Remove empty leading/trailing fields from splitting if surroundings were
    # purely unquoted expansions producing nothing.
    cleaned = [f for f in fields if f != ""]
    if for_assign:
        return cleaned or [""]
    out = []
    for f in cleaned:
        out.extend(_pathname_expand(f, shell))
    return out or []


def _all_splittable_empty(pieces):
    for text, splittable, quoted in pieces:
        if quoted:
            return False
        if text != "":
            return False
    return True


def _expand_dquote(text, shell):
    """Expand $... and `...` sequences inside a double-quoted string."""
    out = []
    i = 0
    n = len(text)
    while i < n:
        c = text[i]
        if c == "$":
            seg, ni = _read_dollar_in_dquote(text, i)
            i = ni
            kind = seg[0]
            if kind == "V":
                out.append(shell.get_var(seg[1]))
            elif kind == "VB":
                out.append(_expand_vb(seg[1], shell))
            elif kind == "A":
                out.append(str(_arith(seg[1], shell)))
            elif kind == "C":
                v = shell.command_subst(seg[1])
                while v.endswith("\n"):
                    v = v[:-1]
                out.append(v)
            else:
                out.append("$")
            continue
        if c == "`":
            j = i + 1
            buf = []
            while j < n and text[j] != "`":
                if text[j] == "\\" and j + 1 < n:
                    buf.append(text[j + 1])
                    j += 2
                    continue
                buf.append(text[j])
                j += 1
            v = shell.command_subst("".join(buf))
            while v.endswith("\n"):
                v = v[:-1]
            out.append(v)
            i = j + 1
            continue
        out.append(c)
        i += 1
    return "".join(out)


def _read_dollar_in_dquote(text, i):
    n = len(text)
    assert text[i] == "$"
    if i + 1 >= n:
        return ("R", "$"), i + 1
    c = text[i + 1]
    if c == "{":
        j = i + 2
        depth = 1
        while j < n and depth > 0:
            if text[j] == "{":
                depth += 1
            elif text[j] == "}":
                depth -= 1
                if depth == 0:
                    break
            j += 1
        return ("VB", text[i + 2 : j]), j + 1
    if c == "(":
        if i + 2 < n and text[i + 2] == "(":
            j = i + 3
            depth = 2
            while j < n and depth > 0:
                if text[j] == "(":
                    depth += 1
                elif text[j] == ")":
                    depth -= 1
                    if depth == 0 and j + 1 < n and text[j + 1] == ")":
                        return ("A", text[i + 3 : j]), j + 2
                j += 1
            return ("R", "$"), i + 1
        j = i + 2
        depth = 1
        while j < n and depth > 0:
            if text[j] == "(":
                depth += 1
            elif text[j] == ")":
                depth -= 1
                if depth == 0:
                    return ("C", text[i + 2 : j]), j + 1
            j += 1
        return ("R", "$"), i + 1
    if c.isalpha() or c == "_":
        j = i + 2
        while j < n and (text[j].isalnum() or text[j] == "_"):
            j += 1
        return ("V", text[i + 1 : j]), j
    if c.isdigit():
        return ("V", c), i + 2
    if c in "?$#@*!-0":
        return ("V", c), i + 2
    return ("R", "$"), i + 1


def _expand_vb(inner, shell):
    """Expand ${...} form. Supports :-, :=, :?, :+, #, %, name, ${#name}."""
    if inner.startswith("#"):
        return str(len(shell.get_var(inner[1:])))
    # Split on first separator operator.
    for op in (":-", ":=", ":?", ":+", "-", "=", "?", "+", "#", "%"):
        idx = _find_modifier(inner, op)
        if idx >= 0:
            name = inner[:idx]
            rest = inner[idx + len(op) :]
            val = shell.get_var(name)
            if op in (":-", "-"):
                if val == "" and (op == ":-" or not shell.is_set(name)):
                    return rest
                if op == "-" and not shell.is_set(name):
                    return rest
                return val
            if op in (":+", "+"):
                if val != "" or (op == "+" and shell.is_set(name)):
                    return rest
                return ""
            if op in (":=", "="):
                if val == "" and (op == ":=" or not shell.is_set(name)):
                    shell.set_var(name, rest)
                    return rest
                return val
            if op in (":?", "?"):
                if val == "" and (op == ":?" or not shell.is_set(name)):
                    import sys
                    sys.stderr.write("nsh: %s: %s\n" % (name, rest or "parameter null or not set"))
                    raise _ExitSignal(1)
                return val
            if op == "#":
                # Prefix match (shortest)
                return _strip_prefix(val, rest, greedy=False)
            if op == "%":
                return _strip_suffix(val, rest, greedy=False)
    return shell.get_var(inner)


def _find_modifier(s, op):
    # Find the operator that's not part of an identifier.
    n = len(op)
    for i in range(len(s) - n + 1):
        if s[i : i + n] == op:
            # For single-char ops, avoid matching part of a longer op like :-.
            if n == 1 and i + 1 < len(s) and s[i] == ":" and s[i + 1] in "-+=?":
                continue
            # Ensure identifier-only before (for standard name forms).
            if i == 0:
                continue  # name must be non-empty
            return i
    return -1


def _strip_prefix(val, pattern, greedy):
    # No glob support for now; just literal match.
    if val.startswith(pattern):
        return val[len(pattern) :]
    return val


def _strip_suffix(val, pattern, greedy):
    if val.endswith(pattern):
        return val[: len(val) - len(pattern)]
    return val


def _pathname_expand(field, shell):
    # Pathname expansion (globbing). If the field contains glob chars and
    # matches files, expand to them.
    import glob
    if any(c in field for c in "*?[") and not field.startswith("-"):
        matches = sorted(glob.glob(field))
        if matches:
            return matches
    return [field]


def _pathname_expand_single(field, had_quoted, shell):
    if had_quoted:
        return field
    # Not used for globbing here because we return list elsewhere.
    return field


class _ExitSignal(Exception):
    def __init__(self, code):
        self.code = code


# ------- arithmetic -------


def _arith(expr, shell):
    """Evaluate an arithmetic expression. Returns an int."""
    # First, expand $var and bare names to their values as ints.
    tokens = _arith_tokenize(expr)
    # Convert bare names to their variable values.
    p = _ArithParser(tokens, shell)
    val = p.parse_expr()
    return int(val)


def _arith_tokenize(expr):
    i = 0
    n = len(expr)
    out = []
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and (expr[j].isdigit() or expr[j] in "xXabcdefABCDEF"):
                j += 1
            out.append(("num", expr[i:j]))
            i = j
            continue
        if c.isalpha() or c == "_":
            j = i
            while j < n and (expr[j].isalnum() or expr[j] == "_"):
                j += 1
            out.append(("name", expr[i:j]))
            i = j
            continue
        if c == "$":
            # $name or ${name}
            if i + 1 < n and expr[i + 1] == "{":
                j = expr.find("}", i + 2)
                out.append(("name", expr[i + 2 : j]))
                i = j + 1
                continue
            j = i + 1
            while j < n and (expr[j].isalnum() or expr[j] == "_"):
                j += 1
            out.append(("name", expr[i + 1 : j]))
            i = j
            continue
        # Multi-char operators
        for op in ("<<", ">>", "<=", ">=", "==", "!=", "&&", "||", "**"):
            if expr.startswith(op, i):
                out.append(("op", op))
                i += len(op)
                break
        else:
            out.append(("op", c))
            i += 1
    out.append(("eof", ""))
    return out


class _ArithParser:
    def __init__(self, tokens, shell):
        self.t = tokens
        self.p = 0
        self.sh = shell

    def peek(self):
        return self.t[self.p]

    def eat(self):
        t = self.t[self.p]
        self.p += 1
        return t

    def match(self, kind, val=None):
        t = self.peek()
        if t[0] == kind and (val is None or t[1] == val):
            return self.eat()
        return None

    def parse_expr(self):
        return self.parse_assign()

    def parse_assign(self):
        # Left must be name for assignment.
        start = self.p
        if self.peek()[0] == "name" and self.t[self.p + 1] == ("op", "="):
            name = self.eat()[1]
            self.eat()  # '='
            val = self.parse_assign()
            self.sh.set_var(name, str(val))
            return val
        return self.parse_or()

    def parse_or(self):
        left = self.parse_and()
        while self.peek() == ("op", "||"):
