                    os.dup2(new_fd, fd)
                    os.close(new_fd)
                elif op == "<":
                    new_fd = os.open(target, os.O_RDONLY)
                    os.dup2(new_fd, fd)
                    os.close(new_fd)
                elif op == ">&":
                    if target == "-":
                        os.close(fd)
                    else:
                        try:
                            src = int(target)
                        except ValueError:
                            src = 1
                        os.dup2(src, fd)
                elif op == "<&":
                    if target == "-":
                        os.close(fd)
                    else:
                        try:
                            src = int(target)
                        except ValueError:
                            src = 0
