            return 2
        args = args[:-1]
    return 0 if _test_eval(args) else 1


def _test_eval(args):
    n = len(args)
    if n == 0:
        return False
    if n == 1:
        return args[0] != ""
    if n == 2:
        op = args[0]
        v = args[1]
        if op == "!":
            return not _test_eval([v])
        if op == "-z":
            return v == ""
        if op == "-n":
            return v != ""
        if op == "-e":
            return os.path.exists(v)
        if op == "-f":
            return os.path.isfile(v)
        if op == "-d":
            return os.path.isdir(v)
        if op == "-r":
