            return _to_int(a) == _to_int(b)
        if op == "-ne":
            return _to_int(a) != _to_int(b)
        if op == "-lt":
            return _to_int(a) < _to_int(b)
        if op == "-le":
            return _to_int(a) <= _to_int(b)
        if op == "-gt":
            return _to_int(a) > _to_int(b)
        if op == "-ge":
            return _to_int(a) >= _to_int(b)
