    try:
        return int(s)
    except ValueError:
        return 0


def _b_return(shell, argv):
    code = 0
    if len(argv) > 1:
        try:
            code = int(argv[1]) & 0xFF
        except ValueError:
            code = 0
    raise ReturnException(code)


def _b_break(shell, argv):
    n = 1
    if len(argv) > 1:
        try:
            n = int(argv[1])
        except ValueError:
            n = 1
    raise BreakException(n)


def _b_continue(shell, argv):
    n = 1
    if len(argv) > 1:
        try:
            n = int(argv[1])
        except ValueError:
            n = 1
