"""Shell execution engine: walks the AST and runs commands."""

import fnmatch
import os
import signal
import sys

from . import expand
from . import lexer
from . import parser as _parser


class ExitException(Exception):
    def __init__(self, code):
        self.code = code


class BreakException(Exception):
    def __init__(self, n=1):
        self.n = n


class ContinueException(Exception):
    def __init__(self, n=1):
        self.n = n


class ReturnException(Exception):
    def __init__(self, code=0):
        self.code = code


class Shell:
    def __init__(self, argv0="nsh", positional=None, interactive=False):
        self.vars = {}              # user-set variables (non-exported)
        self.exported = set()       # names of exported variables
        self.env_copy = dict(os.environ)
        for k, v in self.env_copy.items():
            self.vars[k] = v
            self.exported.add(k)
        self.last_status = 0
        self.positional = list(positional) if positional else []
        self.argv0 = argv0
        self.aliases = {}
        self.functions = {}
        self.interactive = interactive

    # ---- variables ----
    def get_var(self, name):
        if name == "?":
            return str(self.last_status)
        if name == "$":
            return str(os.getpid())
        if name == "#":
            return str(len(self.positional))
        if name == "@":
            return " ".join(self.positional)  # field splitting varies by context
        if name == "*":
            return " ".join(self.positional)
        if name == "-":
            return ""
        if name == "!":
            return ""
        if name == "0":
            return self.argv0
        if name.isdigit():
            idx = int(name)
            if 1 <= idx <= len(self.positional):
                return self.positional[idx - 1]
            return ""
        return self.vars.get(name, "")

    def is_set(self, name):
        if name == "?" or name == "$" or name == "#" or name == "@" or name == "*":
            return True
        if name.isdigit():
            idx = int(name)
            return 1 <= idx <= len(self.positional)
        return name in self.vars

    def set_var(self, name, value):
        self.vars[name] = value
        if name in self.exported:
            os.environ[name] = value

    def export_var(self, name, value=None):
        if value is not None:
            self.vars[name] = value
        self.exported.add(name)
        os.environ[name] = self.vars.get(name, "")

    def unset_var(self, name):
        self.vars.pop(name, None)
        self.exported.discard(name)
        os.environ.pop(name, None)

    # ---- execution ----
    def run_source(self, text):
        try:
            tokens = lexer.tokenize(text)
        except lexer.LexError as e:
            sys.stderr.write("nsh: lex error: %s\n" % e)
            self.last_status = 1
            return self.last_status
        try:
            prog = _parser.Parser(tokens).parse_program()
        except _parser.ParseError as e:
            sys.stderr.write("nsh: parse error: %s\n" % e)
            self.last_status = 1
            return self.last_status
        return self.run_program(prog)

    def run_program(self, program):
        for stmt in program:
            self.run_node(stmt)
        return self.last_status

    def run_node(self, node):
        k = node["kind"]
        if k == "simple":
            return self.run_simple(node)
        if k == "pipeline":
            return self.run_pipeline(node)
        if k == "and_or":
            return self.run_and_or(node)
        if k == "if":
            return self.run_if(node)
        if k == "for":
            return self.run_for(node)
        if k == "while":
            return self.run_while(node)
        if k == "case":
            return self.run_case(node)
        if k == "group":
            with _redirs(node.get("redirs", []), self):
                rc = 0
                for s in node["body"]:
                    rc = self.run_node(s)
                self.last_status = rc
                return rc
        if k == "subshell":
            pid = os.fork()
            if pid == 0:
                try:
                    with _redirs(node.get("redirs", []), self):
                        rc = 0
                        for s in node["body"]:
                            rc = self.run_node(s)
                except ExitException as e:
                    rc = e.code
                os._exit(rc)
            _, status = os.waitpid(pid, 0)
            rc = _decode_status(status)
            self.last_status = rc
            return rc
        if k == "func":
            self.functions[node["name"]] = node["body"]
            self.last_status = 0
            return 0
        raise RuntimeError("unknown node: %s" % k)

    def run_and_or(self, node):
        rc = self.run_node(node["pipes"][0])
        for i, op in enumerate(node["ops"]):
            next_pipe = node["pipes"][i + 1]
            if op == "&&":
                if rc == 0:
                    rc = self.run_node(next_pipe)
            elif op == "||":
                if rc != 0:
                    rc = self.run_node(next_pipe)
        return rc

    def run_pipeline(self, node):
        cmds = node["cmds"]
        negate = node.get("negate", False)
        if len(cmds) == 1:
            rc = self.run_node(cmds[0])
            if negate:
                rc = 1 if rc == 0 else 0
            self.last_status = rc
            return rc
        # Multi-stage pipeline: use fork for each stage.
        pipes = [os.pipe() for _ in range(len(cmds) - 1)]
        pids = []
        for i, cmd in enumerate(cmds):
            pid = os.fork()
            if pid == 0:
                # Child: wire up fds.
                if i > 0:
                    os.dup2(pipes[i - 1][0], 0)
                if i < len(cmds) - 1:
                    os.dup2(pipes[i][1], 1)
                # Close all pipe fds.
                for r, w in pipes:
                    os.close(r)
                    os.close(w)
                try:
                    rc = self.run_node(cmd)
                except ExitException as e:
                    rc = e.code
                sys.stdout.flush()
                sys.stderr.flush()
                os._exit(rc & 0xFF)
            pids.append(pid)
        # Parent: close all pipe fds.
        for r, w in pipes:
            os.close(r)
            os.close(w)
        rc = 0
        for pid in pids:
            _, status = os.waitpid(pid, 0)
            rc = _decode_status(status)
        if negate:
            rc = 1 if rc == 0 else 0
        self.last_status = rc
        return rc

    def run_if(self, node):
        with _redirs(node.get("redirs", []), self):
            for cond, body in node["branches"]:
                rc = 0
                for s in cond:
                    rc = self.run_node(s)
                if rc == 0:
                    rc2 = 0
                    for s in body:
                        rc2 = self.run_node(s)
                    self.last_status = rc2
                    return rc2
            if node["else"] is not None:
                rc2 = 0
                for s in node["else"]:
                    rc2 = self.run_node(s)
                self.last_status = rc2
                return rc2
        self.last_status = 0
        return 0

    def run_for(self, node):
        with _redirs(node.get("redirs", []), self):
            if node["items"] is None:
                items = list(self.positional)
            else:
                items = []
                for w in node["items"]:
                    items.extend(expand.expand_word(w.value, self))
            rc = 0
            for val in items:
                self.set_var(node["var"], val)
                try:
                    for s in node["body"]:
                        rc = self.run_node(s)
                except BreakException as b:
                    if b.n > 1:
                        raise BreakException(b.n - 1)
                    break
                except ContinueException as c:
                    if c.n > 1:
                        raise ContinueException(c.n - 1)
                    continue
            self.last_status = rc
            return rc

    def run_while(self, node):
        with _redirs(node.get("redirs", []), self):
            rc = 0
            negate = node.get("negate", False)
            while True:
                crc = 0
                for s in node["cond"]:
                    crc = self.run_node(s)
                if negate:
                    if crc == 0:
                        break
                else:
                    if crc != 0:
                        break
                try:
                    for s in node["body"]:
                        rc = self.run_node(s)
                except BreakException as b:
                    if b.n > 1:
                        raise BreakException(b.n - 1)
                    break
                except ContinueException as c:
                    if c.n > 1:
                        raise ContinueException(c.n - 1)
                    continue
            self.last_status = rc
            return rc

    def run_case(self, node):
        with _redirs(node.get("redirs", []), self):
            word_vals = expand.expand_word(node["word"].value, self)
            word = word_vals[0] if word_vals else ""
            for patterns, body in node["items"]:
                for pat_tok in patterns:
                    pats = expand.expand_word(pat_tok.value, self)
                    for pat in pats:
                        if fnmatch.fnmatchcase(word, pat):
                            rc = 0
                            for s in body:
                                rc = self.run_node(s)
                            self.last_status = rc
                            return rc
            self.last_status = 0
            return 0

    def run_simple(self, node):
        # Expand assignments and argv.
        assigns = node["assigns"]
        argv_tokens = node["argv"]
        redirs = node["redirs"]

        argv = []
        for t in argv_tokens:
            argv.extend(expand.expand_word(t.value, self))

        if not argv:
            # Assignment-only command: assignments are permanent.
            for name, val_form in assigns:
                vals = expand.expand_word(val_form, self, for_assign=True)
                self.set_var(name, " ".join(vals) if vals else "")
            self.last_status = 0
            return 0

        # Alias substitution.
        if argv[0] in self.aliases:
            # Naive alias expansion.
            replacement = self.aliases[argv[0]]
            try:
                tokens = lexer.tokenize(replacement)
                parts = []
                for tok in tokens:
                    if tok.kind == "WORD":
                        parts.extend(expand.expand_word(tok.value, self))
                argv = parts + argv[1:]
            except lexer.LexError:
                pass

        # Function invocation.
        if argv[0] in self.functions:
            return self._call_function(argv, assigns, redirs)

        # Apply redirs (non-builtin commands fork, so we apply only within
        # the child process; for builtins, we apply in-place).
        cmd = argv[0]
        if cmd in BUILTINS or cmd == ":":
            # Apply assignments only for the builtin's duration.
            saved = self._snapshot_vars([a[0] for a in assigns])
            for name, val_form in assigns:
                vals = expand.expand_word(val_form, self, for_assign=True)
                self.set_var(name, " ".join(vals) if vals else "")
            try:
                with _redirs(redirs, self):
                    rc = BUILTINS[cmd](self, argv)
            finally:
                self._restore_vars(saved)
            self.last_status = rc
            return rc

        # External command: fork + exec.
        # Prepare env: temporarily apply assignments as exported.
        added_env = {}
        old_env = {}
        for name, val_form in assigns:
            vals = expand.expand_word(val_form, self, for_assign=True)
            v = " ".join(vals) if vals else ""
            old_env[name] = os.environ.get(name)
            os.environ[name] = v
            added_env[name] = v

        pid = os.fork()
        if pid == 0:
            # Child
            try:
                _apply_redirs(redirs, self)
            except Exception as e:
                sys.stderr.write("nsh: %s\n" % e)
                os._exit(1)
            try:
                os.execvp(cmd, argv)
            except FileNotFoundError:
                sys.stderr.write("nsh: command not found `%s'\n" % cmd)
                os._exit(127)
            except PermissionError:
                sys.stderr.write("nsh: %s: permission denied\n" % cmd)
                os._exit(126)
            except OSError as e:
                sys.stderr.write("nsh: %s: %s\n" % (cmd, e))
                os._exit(127)

        # Parent: wait & restore env.
        _, status = os.waitpid(pid, 0)
        rc = _decode_status(status)
        for name, prev in old_env.items():
            if prev is None:
                os.environ.pop(name, None)
            else:
                os.environ[name] = prev
        self.last_status = rc
        return rc

    def _snapshot_vars(self, names):
        return {n: (self.vars.get(n), n in self.exported) for n in names}

    def _restore_vars(self, snap):
        for n, (v, exp) in snap.items():
            if v is None:
                self.vars.pop(n, None)
            else:
                self.vars[n] = v
            if exp:
                self.exported.add(n)
            else:
                self.exported.discard(n)

    def _call_function(self, argv, assigns, redirs):
        body = self.functions[argv[0]]
        saved_pos = self.positional
        self.positional = argv[1:]
        try:
            with _redirs(redirs, self):
                # Apply assignments as local-like (but actually we keep them
                # global for simplicity).
                for name, val_form in assigns:
                    vals = expand.expand_word(val_form, self, for_assign=True)
                    self.set_var(name, " ".join(vals) if vals else "")
                try:
                    rc = self.run_node(body)
                except ReturnException as r:
                    rc = r.code
        finally:
            self.positional = saved_pos
        self.last_status = rc
        return rc

    def command_subst(self, code):
        r, w = os.pipe()
        pid = os.fork()
        if pid == 0:
            try:
                os.close(r)
                os.dup2(w, 1)
                os.close(w)
                rc = self.run_source(code)
            except ExitException as e:
                rc = e.code
            sys.stdout.flush()
            os._exit(rc)
        os.close(w)
        out = b""
        while True:
            chunk = os.read(r, 4096)
            if not chunk:
                break
            out += chunk
        os.close(r)
        _, status = os.waitpid(pid, 0)
        self.last_status = _decode_status(status)
        return out.decode("utf-8", errors="replace")


def _decode_status(status):
    if os.WIFEXITED(status):
        return os.WEXITSTATUS(status)
    if os.WIFSIGNALED(status):
        return 128 + os.WTERMSIG(status)
    return 1


# ------- redirections -------


class _redirs:
    def __init__(self, redirs, shell):
        self.redirs = redirs
        self.shell = shell
        self.saved = []

    def __enter__(self):
        for r in self.redirs:
            fd = r["fd"]
            op = r["op"]
            target_tok = r["target"]
            target_vals = expand.expand_word(target_tok.value, self.shell)
            target = target_vals[0] if target_vals else ""
            saved_fd = os.dup(fd) if _fd_open(fd) else None
            try:
                if op == ">":
                    new_fd = os.open(target, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o644)
                    os.dup2(new_fd, fd)
                    os.close(new_fd)
                elif op == ">>":
                    new_fd = os.open(target, os.O_WRONLY | os.O_CREAT | os.O_APPEND, 0o644)
                    os.dup2(new_fd, fd)
                    os.close(new_fd)
                elif op == "<":
                    new_fd = os.open(target, os.O_RDONLY)
                    os.dup2(new_fd, fd)
                    os.close(new_fd)
                elif op == ">&":
                    if target == "-":
                        os.close(fd)
                    else:
                        try:
                            src = int(target)
                        except ValueError:
                            src = 1
                        os.dup2(src, fd)
                elif op == "<&":
                    if target == "-":
                        os.close(fd)
                    else:
                        try:
                            src = int(target)
                        except ValueError:
                            src = 0
                        os.dup2(src, fd)
            except Exception:
                raise
            self.saved.append((fd, saved_fd))
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        for fd, saved in reversed(self.saved):
            try:
                if saved is not None:
                    os.dup2(saved, fd)
                    os.close(saved)
                else:
                    try:
                        os.close(fd)
                    except OSError:
                        pass
            except OSError:
                pass
        return False


def _fd_open(fd):
    try:
        os.fstat(fd)
        return True
    except OSError:
        return False


def _apply_redirs(redirs, shell):
    """Apply redirections permanently (used in child processes)."""
    for r in redirs:
        fd = r["fd"]
        op = r["op"]
        target_vals = expand.expand_word(r["target"].value, shell)
        target = target_vals[0] if target_vals else ""
        if op == ">":
            new_fd = os.open(target, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o644)
            os.dup2(new_fd, fd)
            os.close(new_fd)
        elif op == ">>":
            new_fd = os.open(target, os.O_WRONLY | os.O_CREAT | os.O_APPEND, 0o644)
            os.dup2(new_fd, fd)
            os.close(new_fd)
        elif op == "<":
            new_fd = os.open(target, os.O_RDONLY)
            os.dup2(new_fd, fd)
            os.close(new_fd)
        elif op == ">&":
            if target == "-":
                os.close(fd)
            else:
                try:
                    src = int(target)
                except ValueError:
                    src = 1
                os.dup2(src, fd)
        elif op == "<&":
            if target == "-":
                os.close(fd)
            else:
                try:
                    src = int(target)
                except ValueError:
                    src = 0
                os.dup2(src, fd)


# ------- builtins -------


def _b_echo(shell, argv):
    # Minimal echo: supports -n; no -e.
    args = argv[1:]
    newline = True
    if args and args[0] == "-n":
        newline = False
        args = args[1:]
    sys.stdout.write(" ".join(args))
    if newline:
        sys.stdout.write("\n")
    sys.stdout.flush()
    return 0


def _b_cd(shell, argv):
    if len(argv) < 2:
        target = shell.get_var("HOME") or os.path.expanduser("~")
    else:
        target = argv[1]
    if target == "-":
        target = shell.get_var("OLDPWD")
        if not target:
            sys.stderr.write("nsh: cd: OLDPWD not set\n")
            return 1
        sys.stdout.write(target + "\n")
    old = os.getcwd()
    try:
        os.chdir(target)
    except FileNotFoundError:
        sys.stderr.write("nsh: cd: %s: No such file or directory\n" % target)
        return 1
    except NotADirectoryError:
        sys.stderr.write("nsh: cd: %s: Not a directory\n" % target)
        return 1
    except PermissionError:
        sys.stderr.write("nsh: cd: %s: Permission denied\n" % target)
        return 1
    shell.set_var("OLDPWD", old)
    shell.set_var("PWD", os.getcwd())
    return 0


def _b_pwd(shell, argv):
    sys.stdout.write(os.getcwd() + "\n")
    sys.stdout.flush()
    return 0


def _b_exit(shell, argv):
    code = 0
    if len(argv) > 1:
        try:
            code = int(argv[1]) & 0xFF
        except ValueError:
            code = 1
    else:
        code = shell.last_status
    raise ExitException(code)


def _b_export(shell, argv):
    if len(argv) == 1:
        for n in sorted(shell.exported):
            v = shell.vars.get(n, "")
            sys.stdout.write("export %s=%s\n" % (n, _shell_quote(v)))
        return 0
    rc = 0
    for arg in argv[1:]:
        if "=" in arg:
            name, val = arg.split("=", 1)
            shell.export_var(name, val)
        else:
            shell.export_var(arg)
    return rc


def _b_unset(shell, argv):
    for name in argv[1:]:
        shell.unset_var(name)
    return 0


def _b_true(shell, argv):
    return 0


def _b_false(shell, argv):
    return 1


def _b_colon(shell, argv):
    return 0


def _b_alias(shell, argv):
    if len(argv) == 1:
        for k, v in sorted(shell.aliases.items()):
            sys.stdout.write("%s='%s'\n" % (k, v))
        return 0
    rc = 0
    for arg in argv[1:]:
        if "=" in arg:
            name, val = arg.split("=", 1)
            shell.aliases[name] = val
        else:
            if arg in shell.aliases:
                sys.stdout.write("%s='%s'\n" % (arg, shell.aliases[arg]))
            else:
                sys.stderr.write("nsh: alias: %s: not found\n" % arg)
                rc = 1
    return rc


def _b_unalias(shell, argv):
    for a in argv[1:]:
        shell.aliases.pop(a, None)
    return 0


def _b_read(shell, argv):
    # Basic read: no options parsed.
    names = argv[1:] or ["REPLY"]
    try:
        line = sys.stdin.readline()
    except Exception:
        return 1
    if not line:
        return 1
    if line.endswith("\n"):
        line = line[:-1]
    # Split by IFS into words, assigning to the given names.
    ifs = shell.get_var("IFS") or " \t\n"
    if len(names) == 1:
        shell.set_var(names[0], line)
        return 0
    parts = []
    cur = ""
    i = 0
    while i < len(line):
        if line[i] in ifs:
            parts.append(cur)
            cur = ""
            while i < len(line) and line[i] in ifs:
                i += 1
            continue
        cur += line[i]
        i += 1
    parts.append(cur)
    for i, n in enumerate(names):
        if i < len(names) - 1:
            shell.set_var(n, parts[i] if i < len(parts) else "")
        else:
            shell.set_var(n, " ".join(parts[i:]))
    return 0


def _b_test(shell, argv):
    args = argv[1:]
    if argv[0] == "[":
        if not args or args[-1] != "]":
            sys.stderr.write("nsh: [: missing `]'\n")
            return 2
        args = args[:-1]
    return 0 if _test_eval(args) else 1


def _test_eval(args):
    n = len(args)
    if n == 0:
        return False
    if n == 1:
        return args[0] != ""
    if n == 2:
        op = args[0]
        v = args[1]
        if op == "!":
            return not _test_eval([v])
        if op == "-z":
            return v == ""
        if op == "-n":
            return v != ""
        if op == "-e":
            return os.path.exists(v)
        if op == "-f":
            return os.path.isfile(v)
        if op == "-d":
            return os.path.isdir(v)
        if op == "-r":
            return os.access(v, os.R_OK)
        if op == "-w":
            return os.access(v, os.W_OK)
        if op == "-x":
            return os.access(v, os.X_OK)
        if op == "-s":
            try:
                return os.path.getsize(v) > 0
            except OSError:
                return False
    if n == 3:
        a, op, b = args
        if op == "=":
            return a == b
        if op == "!=":
            return a != b
        if op == "-eq":
            return _to_int(a) == _to_int(b)
        if op == "-ne":
            return _to_int(a) != _to_int(b)
        if op == "-lt":
            return _to_int(a) < _to_int(b)
        if op == "-le":
            return _to_int(a) <= _to_int(b)
        if op == "-gt":
            return _to_int(a) > _to_int(b)
        if op == "-ge":
            return _to_int(a) >= _to_int(b)
    # Fallback: nonzero if has content.
    return any(a != "" for a in args)


def _to_int(s):
    try:
        return int(s)
    except ValueError:
        return 0


def _b_return(shell, argv):
    code = 0
    if len(argv) > 1:
        try:
            code = int(argv[1]) & 0xFF
        except ValueError:
            code = 0
    raise ReturnException(code)


def _b_break(shell, argv):
    n = 1
    if len(argv) > 1:
        try:
            n = int(argv[1])
        except ValueError:
            n = 1
    raise BreakException(n)


def _b_continue(shell, argv):
    n = 1
    if len(argv) > 1:
        try:
            n = int(argv[1])
        except ValueError:
            n = 1
    raise ContinueException(n)


def _b_source(shell, argv):
    if len(argv) < 2:
        return 1
    try:
        with open(argv[1]) as f:
            text = f.read()
    except OSError as e:
        sys.stderr.write("nsh: .: %s: %s\n" % (argv[1], e.strerror))
        return 1
    return shell.run_source(text)


def _b_shift(shell, argv):
    n = 1
    if len(argv) > 1:
        try:
            n = int(argv[1])
        except ValueError:
            n = 0
    if n > len(shell.positional):
        return 1
    shell.positional = shell.positional[n:]
    return 0


def _b_set(shell, argv):
    # Minimal support: `set -- a b c` resets positional args; no option support.
    if len(argv) > 1 and argv[1] == "--":
        shell.positional = argv[2:]
    return 0


def _shell_quote(s):
    if not s or any(c in s for c in " \t\n'\"\\$`|&;<>()*?[]{}!~#"):
        return "'" + s.replace("'", "'\"'\"'") + "'"
    return s


BUILTINS = {
